/**
 * CI gate reporting: console report, full-metrics table, and the JSON gate
 * report written alongside the k6 summary.
 *
 * Pure formatting + I/O over the evaluated `GateResult[]` and the k6 metrics map.
 *
 * @module gate/report
 */

import * as fs from 'node:fs';
import * as path from 'node:path';

import type { K6Summary, K6Metric } from '../types/index.ts';
import type { GateResult } from './evaluate.ts';
import { isTrendMetric, isRateMetric, isCounterMetric, isGaugeMetric } from './summary_loader.ts';
import { formatBytes } from '../utils/format.ts';
// KS-971: slot identity for the gate report — one home for the derivation.
import { artifactLabel, gatewayPort, resolveSlot, slotTag } from '../utils/stackSlot.ts';

/**
 * Map from metric name substring to a human-readable HTTP status code label.
 * Entries are checked in order; first match wins.
 */
const HTTP_CODE_LABELS: ReadonlyArray<readonly [string, string]> = [
    ['http_rate_limited', '[HTTP 429/503]'],
    ['http_server_error', '[HTTP 5xx]'],
    ['http_req_failed', '[HTTP 4xx/5xx]'],
];

/**
 * The status-code counters the k6 scripts already collect beside `http_req_failed`, in the order a
 * reader triages them (KS-704). Each isolates one class the failure rate cannot: `http_server_error`
 * 5xx, `http_rate_limited` 429/503, `http_503` 503 alone. `http_status_code` is deliberately NOT here —
 * it is a plain Counter with no per-code breakdown (the trap the ticket names).
 *
 * Kept apart from {@link HTTP_CODE_LABELS}: that table labels a gate's headline by substring; this one
 * is the fixed set of SIBLINGS printed under a failed rate gate, so it needs `http_503` (which has no
 * headline label) and must never gain `http_req_failed` (which is the gate itself).
 */
const STATUS_CODE_COUNTERS: ReadonlyArray<readonly [string, string]> = [
    ['http_server_error', '[5xx]'],
    ['http_rate_limited', '[429/503]'],
    ['http_503', '[503]'],
];

/**
 * Return the HTTP status code label for a gate result name, or an empty string.
 *
 * @param {string} name - Gate result name, e.g. `'threshold: http_rate_limited rate<0.01'`.
 * @returns {string} Label such as `'[HTTP 429/503]'`, or `''` when not applicable.
 *
 * @internal
 */
function httpCodeLabel(name: string): string {
    for (const [key, label] of HTTP_CODE_LABELS) {
        if (name.includes(key)) {
            return label;
        }
    }
    return '';
}

/**
 * Whether a gate result is an HTTP-outcome RATE gate — the only kind a status-code breakdown can
 * explain.
 *
 * Both rate-gate shapes `evaluate.ts` produces carry a percentage `actual` (`threshold: http_req_failed
 * rate<0.01` → `0.0023%`; the supplementary `ci: error rate` → `0.0023%`), while trend gates carry
 * `… ms` and counters `…/s` — so the measured value's unit is the discriminator, read off the result
 * rather than re-derived from the metric map. The name clause keeps a failed `checks` rate (a k6
 * check ratio, not an HTTP outcome) from being decorated with status codes it says nothing about.
 *
 * @param {GateResult} result - One evaluated gate.
 * @returns {boolean} `true` for a rate gate about HTTP outcomes.
 *
 * @internal
 */
function isHttpRateGate(result: GateResult): boolean {
    return result.actual.endsWith('%') && /http_|error rate/.test(result.name);
}

/**
 * One line naming the status-code counters, in k6's own words, for the failed rate gate above it.
 *
 * KS-704: the failure RATE alone cannot say whether a platform 5xx, a 429, or a harness auth 4xx
 * produced it — and those need opposite responses. The counters that discriminate are already in the
 * summary; this prints them where the author reads the failure. A counter the summary lacks reads
 * `absent`, never a fabricated `0`: an unprovided metric is not evidence of zero.
 *
 * `passes` / `fails` are k6 Rate semantics — `passes` counts evaluations where the metric was TRUE, so
 * for `http_server_error` `passes=3` means three 5xx responses. The trailer says so on the line itself.
 *
 * @param {K6Summary['metrics']} metrics - The full metrics map from the k6 summary.
 * @returns {string} The indented breakdown line.
 *
 * @internal
 */
function formatStatusCodeBreakdown(metrics: K6Summary['metrics']): string {
    const parts = STATUS_CODE_COUNTERS.map(([name, label]) => {
        const metric = metrics[name];
        // A counter present as a Rate prints its two counts; anything else (absent, or not a Rate) is
        // named as absent so the reader knows the summary did not carry it.
        return isRateMetric(metric)
            ? `${name} ${label} passes=${metric.passes.toLocaleString()} fails=${metric.fails.toLocaleString()}`
            : `${name} ${label} absent`;
    });
    return `     status codes: ${parts.join('  ·  ')}  (k6 Rate: passes = responses where the metric was true)`;
}

/**
 * Format a single k6 metric into a compact human-readable detail string.
 *
 * @param {string} name - Metric name, used to detect byte-valued counters.
 * @param {K6Metric} metric - The metric object from the k6 summary.
 * @returns {string} Formatted detail string for the metrics table row.
 *
 * @internal
 */
function formatMetricDetail(name: string, metric: K6Metric): string {
    // Trend: latency / duration metrics — show avg, key percentiles, and max
    if (isTrendMetric(metric)) {
        const p99 = metric['p(99)'];
        const p99Part = p99 !== undefined ? `  p(99)=${p99.toFixed(0)}ms` : '';
        return `avg=${metric.avg.toFixed(0)}ms  p(95)=${metric['p(95)'].toFixed(0)}ms${p99Part}  max=${metric.max.toFixed(0)}ms`;
    }
    // Rate: pass/fail ratio — percentage is the primary signal, counts give context
    if (isRateMetric(metric)) {
        const pct = (metric.value * 100).toFixed(2);
        // KS-704: `http_req_failed` is a k6 Rate, so `passes` counts requests where "failed" was TRUE —
        // the healthy run printed `(passes=0  fails=37)` and read as 37 failures. Relabel THIS metric
        // only; every other Rate keeps k6's own words so the table still matches the raw summary.
        if (name === 'http_req_failed') {
            return `${pct}%  (failed=${metric.passes.toLocaleString()}  ok=${metric.fails.toLocaleString()})`;
        }
        return `${pct}%  (passes=${metric.passes.toLocaleString()}  fails=${metric.fails.toLocaleString()})`;
    }
    // Counter: byte-valued counters (data_sent, data_received) get human-readable sizes
    if (isCounterMetric(metric)) {
        const isBytes = name.startsWith('data_');
        const countStr = isBytes ? formatBytes(metric.count) : metric.count.toLocaleString();
        const rateStr = isBytes ? `${formatBytes(metric.rate)}/s` : `${metric.rate.toFixed(2)}/s`;
        return `${countStr}  ${rateStr}`;
    }
    // Gauge: current scalar (vus, vus_max) — show value and range
    if (isGaugeMetric(metric)) {
        return `current=${String(metric.value)}  min=${String(metric.min)}  max=${String(metric.max)}`;
    }
    return '—';
}

/**
 * Print a table of every metric returned by k6, sorted alphabetically.
 *
 * @param {K6Summary['metrics']} metrics - The full metrics map from the k6 summary.
 * @returns {void}
 *
 * @internal
 */
export function printAllMetrics(metrics: K6Summary['metrics']): void {
    // Step: collect all present metrics into sortable rows
    const rows: Array<{ name: string; prefix: string; detail: string; codeLabel: string }> = [];

    for (const [name, metric] of Object.entries(metrics)) {
        if (metric === undefined) {
            continue;
        }
        // Step: determine gate outcome prefix for thresholded metrics
        const thresholds = metric.thresholds;
        let prefix: string;
        if (thresholds !== undefined && Object.keys(thresholds).length > 0) {
            // A metric passes its gate only when every threshold expression passes
            const allPassed = Object.values(thresholds).every((breached) => !breached);
            prefix = allPassed ? '✓' : '✗';
        } else {
            prefix = 'ℹ';
        }

        rows.push({
            name,
            prefix,
            detail: formatMetricDetail(name, metric),
            codeLabel: httpCodeLabel(name),
        });
    }

    // Step: sort alphabetically so related metrics (http_req_*) cluster together
    rows.sort((a, b) => a.name.localeCompare(b.name));

    console.log('-'.repeat(60));
    console.log('  k6 Metrics');
    console.log('-'.repeat(60));

    // Step: find the longest name for column alignment
    const nameWidth = Math.max(...rows.map((r) => r.name.length), 24);

    for (const { name, prefix, detail, codeLabel } of rows) {
        const namePadded = name.padEnd(nameWidth);
        const label = codeLabel ? `  ${codeLabel}` : '';
        console.log(`  ${prefix} ${namePadded}  ${detail}${label}`);
    }

    console.log('');
}

/**
 * Print one gate's lines: the headline, its `actual`/`limit` line, and — for a FAILED HTTP rate gate —
 * the status-code breakdown (KS-704). Passed gates go to stdout, failed ones to stderr, so the
 * breakdown follows its gate on the same stream, directly under the lines the author is reading.
 *
 * @param {GateResult} r - One evaluated gate.
 * @param {K6Summary['metrics']} metrics - The k6 metrics map the breakdown reads its counters from.
 * @returns {void}
 *
 * @internal
 */
function printGateLines(r: GateResult, metrics: K6Summary['metrics']): void {
    const icon = r.passed ? '✓' : '✗';
    const codeLabel = httpCodeLabel(r.name);
    // Pad the name to 50 chars so the HTTP code label aligns in a consistent column
    const namePadded = `  ${icon} ${r.name}`.padEnd(54);
    const headline = codeLabel ? `${namePadded} ${codeLabel}` : namePadded.trimEnd();
    const stream = r.passed ? 'log' : 'error';
    console[stream](headline);
    console[stream](`     actual=${r.actual}  limit=${r.limit}`);
    // KS-704: only a FAILED HTTP rate gate earns the breakdown — a passing gate keeps the two-line
    // shape every reader already knows, and a trend/counter gate has no status codes to explain it.
    if (!r.passed && isHttpRateGate(r)) {
        console.error(formatStatusCodeBreakdown(metrics));
    }
}

/**
 * Print a formatted gate report.
 *
 * @param {GateResult[]} results - Evaluated gate results.
 * @param {string} scenario - Scenario name for the report header.
 * @param {boolean} blocking - Whether failures exit non-zero.
 * @param {K6Summary['metrics']} [metrics] - The k6 metrics map, so a FAILED rate gate can name the
 *   status-code counters that explain it (KS-704). Optional: a caller without the summary gets the
 *   report it always got, minus the breakdown.
 * @returns {void}
 * @example
 *   printReport(results, 'smoke', true, summary.metrics);
 *
 * @internal
 */
export function printReport(
    results: GateResult[],
    scenario: string,
    blocking: boolean,
    metrics: K6Summary['metrics'] = {},
): void {
    const failed = results.filter((r) => !r.passed);
    const passed = results.filter((r) => r.passed);

    console.log('\n' + '='.repeat(60));
    console.log(`  CI Gate Report — ${scenario}${blocking ? ' (BLOCKING release gate)' : ' (advisory)'}`);
    // KS-971 (§5a parity): the same slot identity the JSON gate report carries. Four concurrent
    // slots previously printed four identical headers, so a scrollback line could not be attributed.
    console.log(`  Stack slot   : ${slotTag()}  (gateway port ${String(gatewayPort())})`);
    console.log('='.repeat(60));

    for (const r of results) {
        printGateLines(r, metrics);
    }

    console.log(`\n  Passed: ${passed.length} / ${results.length}`);

    if (failed.length === 0) {
        console.log('  Status: ALL GATES PASSED ✓');
    } else {
        console.error(`  Status: ${failed.length} GATE(S) FAILED ✗`);
        if (!blocking) {
            console.log('  (Advisory scenario — pipeline will not be halted)');
        }
    }

    console.log('='.repeat(60) + '\n');
}

/**
 * Read the run's machine-contention flags from the `run-metadata.json` beside its summary.
 *
 * Where/when: called by {@link writeGateReport} so the verdict carries the same contention facts
 * the runner recorded, without the gate having to re-probe Docker (by gate time the neighbours may
 * have changed, and a verdict must describe the run, not the moment it was scored).
 *
 * @param {string} summaryPath - Path to this run's summary; its directory holds the metadata.
 * @returns {Record<string, unknown>} The contention fields, or `{}` when the metadata is absent or
 *   unreadable — an older run folder must still produce a gate report.
 *
 * @internal
 */
function readMachineShared(summaryPath: string): Record<string, unknown> {
    try {
        const metaPath = path.join(path.dirname(summaryPath), 'run-metadata.json');
        if (!fs.existsSync(metaPath)) {
            return {};
        }
        const meta = JSON.parse(fs.readFileSync(metaPath, 'utf8')) as Record<string, unknown>;
        if (typeof meta['machineShared'] !== 'boolean') {
            return {};
        }
        return {
            machineShared: meta['machineShared'],
            stacksRunning: meta['stacksRunning'],
            slotsRunning: meta['slotsRunning'],
        };
    } catch {
        return {};
    }
}

/**
 * Write gate results as a JSON report alongside the k6 summary.
 *
 * @param {GateResult[]} results - Evaluated gate results.
 * @param {string} summaryPath - Path to the k6 summary file.
 * @param {string} scenario - Scenario name.
 * @returns {void}
 *
 * @internal
 */
export function writeGateReport(results: GateResult[], summaryPath: string, scenario: string): void {
    const reportPath = summaryPath.replace(/-summary\.json$/, '-gate-report.json');
    const slot = resolveSlot();
    const report = {
        scenario,
        // KS-971: the gate VERDICT is the artifact people quote — "slot 3 failed" — and it carried
        // no slot at all, only a scenario and a timestamp. With four slots running the same scenario
        // concurrently, two gate reports were distinguishable only by the folder path they sat in.
        // Read from utils/stackSlot.ts rather than passed in: writeGateReport already takes three
        // parameters, and adding more for values with one correct source is how signatures rot.
        slot,
        slotTag: slotTag(slot),
        gatewayPort: gatewayPort(slot),
        runLabel: artifactLabel(),
        // KS-971: carry the contention flag onto the VERDICT, not only the run metadata. The gate
        // report is the artifact people quote; a `passed: true` from a four-slot run is a statement
        // about isolation and never about latency, so it has to say so standing on its own.
        ...readMachineShared(summaryPath),
        timestamp: new Date().toISOString(),
        passed: results.every((r) => r.passed),
        results,
    };
    fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
    console.log(`[ci-gate] Gate report written: ${reportPath}`);
}

