 * WHY ON THE VERDICT AND NOT ONLY THE RUN METADATA. The gate report is the artifact people quote —
 * "slot 3 failed", pasted into a ticket, detached from its folder. A `passed: true` produced by a
 * four-slot run is a statement about ISOLATION and never about latency, so it has to say so
 * standing on its own.
 *
 * The values are read from the sibling `run-metadata.json` rather than re-probed, because by gate
 * time the neighbouring stacks may have changed and a verdict must describe the run, not the moment
 * it was scored.
 */

import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { writeGateReport } from '../../../gate/report.ts';
import type { GateResult } from '../../../gate/evaluate.ts';

let runDir: string;

const RESULTS: GateResult[] = [{ name: 'ci: error rate', passed: true, actual: '0.0000%', limit: '≤ 5.0000%' }];

/** The gate derives the report path from the summary path, so only the name matters here. */
function summaryPath(): string {
    return path.join(runDir, 'smoke-summary.json');
}

/**
 * Read back the gate report the writer produced.
 *
 * @returns {Record<string, unknown>} The parsed gate report.
 */
function readReport(): Record<string, unknown> {
    return JSON.parse(fs.readFileSync(path.join(runDir, 'smoke-gate-report.json'), 'utf8')) as Record<string, unknown>;
}

beforeEach(() => {
    runDir = fs.mkdtempSync(path.join(os.tmpdir(), 'perf-gate-shared-'));
});
afterEach(() => {
    fs.rmSync(runDir, { recursive: true, force: true });
});

describe('writeGateReport — machine contention', () => {
    it('copies machineShared, stacksRunning and slotsRunning from the run metadata', () => {
        fs.writeFileSync(
            path.join(runDir, 'run-metadata.json'),
            JSON.stringify({
                machineShared: true,
                stacksRunning: 4,
                slotsRunning: ['slot1', 'slot2', 'slot3', 'slot4'],
            }),
        );

        writeGateReport(RESULTS, summaryPath(), 'smoke');

        const report = readReport();
        expect(report['machineShared']).toBe(true);
        expect(report['stacksRunning']).toBe(4);
        expect(report['slotsRunning']).toEqual(['slot1', 'slot2', 'slot3', 'slot4']);
    });

    it('records an uncontended run as machineShared false rather than omitting it', () => {
        fs.writeFileSync(
            path.join(runDir, 'run-metadata.json'),
            JSON.stringify({ machineShared: false, stacksRunning: 1, slotsRunning: ['slot1'] }),
        );

        writeGateReport(RESULTS, summaryPath(), 'smoke');

        // An explicit `false` is the whole value of the flag: it is what lets a figure be quoted.
        expect(readReport()['machineShared']).toBe(false);
    });

    it('still writes a verdict when the run metadata is absent', () => {
        // An older run folder, or a gate invoked against a hand-assembled directory, must not fail.
        writeGateReport(RESULTS, summaryPath(), 'smoke');

        const report = readReport();
        expect(report['passed']).toBe(true);
        expect(report).not.toHaveProperty('machineShared');
    });

    it('ignores unreadable or malformed run metadata rather than throwing', () => {
        fs.writeFileSync(path.join(runDir, 'run-metadata.json'), '{ not json');

        expect(() => {
            writeGateReport(RESULTS, summaryPath(), 'smoke');
        }).not.toThrow();
        expect(readReport()['passed']).toBe(true);
    });

    it('ignores metadata whose machineShared is not a boolean', () => {
        // A partially-written or hand-edited file must not put a string into the verdict.
        fs.writeFileSync(path.join(runDir, 'run-metadata.json'), JSON.stringify({ machineShared: 'yes' }));

        writeGateReport(RESULTS, summaryPath(), 'smoke');

        expect(readReport()).not.toHaveProperty('machineShared');
    });
});
